      "h12-1": {"ambiguity_alpha": 0.223064, "discrepancy_delta_mean": 3.124677, "discrepancy_delta_std": 1.788919, "discrepancy_delta_median": 2.8125, "n_concordant_correct": 1427, "disagreement_distribution": {"0_of_3": 419, "1_of_3": 226, "2_of_3": 304, "3_of_3": 1427}, "n_samples": 2376},
      "h6-1": {"ambiguity_alpha": 0.201178, "discrepancy_delta_mean": 2.321217, "discrepancy_delta_std": 1.510742, "discrepancy_delta_median": 2.0, "n_concordant_correct": 1469, "disagreement_distribution": {"0_of_3": 429, "1_of_3": 191, "2_of_3": 287, "3_of_3": 1469}, "n_samples": 2376},
