      "h12-1": {"ambiguity_alpha": 0.315932, "discrepancy_delta_mean": 0.545544, "discrepancy_delta_std": 0.409817, "discrepancy_delta_median": 0.464111, "n_concordant_correct": 1824, "disagreement_distribution": {"0_of_3": 1701, "1_of_3": 763, "2_of_3": 865, "3_of_3": 1824}, "n_samples": 5153},
      "h6-1": {"ambiguity_alpha": 0.293615, "discrepancy_delta_mean": 0.531844, "discrepancy_delta_std": 0.404355, "discrepancy_delta_median": 0.436768, "n_concordant_correct": 1828, "disagreement_distribution": {"0_of_3": 1812, "1_of_3": 690, "2_of_3": 823, "3_of_3": 1828}, "n_samples": 5153},
