      "h3-1": {"ambiguity_alpha": 0.453517, "n_ambiguous": 1483, "disagreement_distribution": {"0_of_3": 556, "1_of_3": 644, "2_of_3": 839, "3_of_3": 1231}, "n_samples": 3270}
